import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.EUByU7Iq.js";const p=JSON.parse('{"title":"第十三章 外国公司的分支机构","description":"","frontmatter":{"title":"第十三章 外国公司的分支机构","date":"2023-12-29T00:00:00.000Z","categories":["法律","公司法"],"tags":["法律","公司法"],"law_version":"2023修订（2023-12-29 公布，2024-07-01 施行）","v1_source":"blogs/CL/第十三章：外国公司的分支机构.md"},"headers":[],"relativePath":"blogs/CL/dishisanzhang：waiguogongsidefenzhijigou.md","filePath":"blogs/CL/第十三章：外国公司的分支机构.md"}'),i={name:"blogs/CL/dishisanzhang：waiguogongsidefenzhijigou.md"};function h(l,a,n,s,d,_){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="第十三章-外国公司的分支机构" tabindex="-1">第十三章 外国公司的分支机构 <a class="header-anchor" href="#第十三章-外国公司的分支机构" aria-label="Permalink to &quot;第十三章 外国公司的分支机构&quot;">​</a></h1><h3 id="第二百四十三条" tabindex="-1">第二百四十三条 <a class="header-anchor" href="#第二百四十三条" aria-label="Permalink to &quot;第二百四十三条&quot;">​</a></h3><p>三条本法所称外国公司，是指依照外国法律在中华人民共和国境外设立的公司。</p><h3 id="第二百四十四条" tabindex="-1">第二百四十四条 <a class="header-anchor" href="#第二百四十四条" aria-label="Permalink to &quot;第二百四十四条&quot;">​</a></h3><p>四条外国公司在中华人民共和国境内设立分支机构，应当向中国主管机关提出申请，并提交其公司章程、所属国的公司登记证书等有关文件，经批准后，向公司登记机关依法办理登记，领取营业执照。 外国公司分支机构的审批办法由国务院另行规定。</p><h3 id="第二百四十五条" tabindex="-1">第二百四十五条 <a class="header-anchor" href="#第二百四十五条" aria-label="Permalink to &quot;第二百四十五条&quot;">​</a></h3><p>五条外国公司在中华人民共和国境内设立分支机构，应当在中华人民共和国境内指定负责该分支机构的代表人或者代理人，并向该分支机构拨付与其所从事的经营活动相适应的资金。 对外国公司分支机构的经营资金需要规定最低限额的，由国务院另行规定。</p><h3 id="第二百四十六条" tabindex="-1">第二百四十六条 <a class="header-anchor" href="#第二百四十六条" aria-label="Permalink to &quot;第二百四十六条&quot;">​</a></h3><p>六条外国公司的分支机构应当在其名称中标明该外国公司的国籍及责任形式。 外国公司的分支机构应当在本机构中置备该外国公司章程。</p><h3 id="第二百四十七条" tabindex="-1">第二百四十七条 <a class="header-anchor" href="#第二百四十七条" aria-label="Permalink to &quot;第二百四十七条&quot;">​</a></h3><p>七条外国公司在中华人民共和国境内设立的分支机构不具有中国法人资格。 外国公司对其分支机构在中华人民共和国境内进行经营活动承担民事责任。</p><h3 id="第二百四十八条" tabindex="-1">第二百四十八条 <a class="header-anchor" href="#第二百四十八条" aria-label="Permalink to &quot;第二百四十八条&quot;">​</a></h3><p>八条经批准设立的外国公司分支机构，在中华人民共和国境内从事业务活动，应当遵守中国的法律，不得损害中国的社会公共利益，其合法权益受中国法律保护。</p><h3 id="第二百四十九条" tabindex="-1">第二百四十九条 <a class="header-anchor" href="#第二百四十九条" aria-label="Permalink to &quot;第二百四十九条&quot;">​</a></h3><p>九条外国公司撤销其在中华人民共和国境内的分支机构时，应当依法清偿债务，依照本法有关公司清算程序的规定进行清算。未清偿债务之前，不得将其分支机构的财产转移至中华人民共和国境外。</p><hr><p class="law-foot">本篇依据《中华人民共和国公司法》2023 年 12 月 29 日第十四届全国人大常委会第七次会议第二次修订文本，自 2024 年 7 月 1 日起施行；本站同步于 2026-11-07。</p>',17)])])}const u=e(i,[["render",h]]);export{p as __pageData,u as default};
